// TestActionNames asserts every announced ui action name is a registered constant.
func TestActionNames(t *testing.T) {

	names := []op.ActionName{
		provider.Error,
		provider.Fail,
		provider.Note,
		provider.Print,
		provider.Succeed,
		provider.Warn,
	}
	for _, name := range names {
		a := getAction(t, name)
		if got := a.Name(); got != name {
			t.Errorf("Name() = %q, want %q", got, name)
		}
	}
}

